const data = Array.isArray($json) ? $json[0] : $json;

// Escape
const escapeMD = (text = "") =>
  String(text)
    .replace(/\\/g, "\\\\")
    .replace(/[_*[\]()~`>#+\-=|{}.!:]/g, "\\$&");

// Dados principais
const fluxo = escapeMD(data.workflow?.name || "Desconhecido");

const node = escapeMD(
  data.execution?.error?.context?.nodeCause ||
  data.execution?.error?.node?.name ||
  data.execution?.lastNodeExecuted ||
  "Desconhecido"
);

// ID da execução
const execIdBruto = data.execution?.id || "";
const exec = escapeMD(execIdBruto || "N/A");

// IDs para montar o link correto
const workflowId = data.workflow?.id || "";
const executionId = execIdBruto;

// Link real do editor
const linkReal = (workflowId && executionId)
  ? `https://new-operadas-wf.macrolabs.app/workflow/${workflowId}/executions/${executionId}`
  : "N/A";

// Link escapado
const linkExec = escapeMD(linkReal);

// Erro completo
const erroBruto =
  data.execution?.error?.message ||
  data.execution?.error?.context?.messageTemplate ||
  data.execution?.error?.stack ||
  "Sem mensagem";

const erro = escapeMD(erroBruto);

// Hora
const dataHora = new Date().toLocaleString("pt-BR").replace(",", " -");
const hora = escapeMD(dataHora);

// Mensagem final
return {
  telegramMessage:
`*ERRO NO N8N*

*Fluxo:* ${fluxo}
*Node:* ${node}
*Execução:* ${exec}
*Horário:* ${hora}

*Detalhes do Erro:*
\`\`\`
${erro}
\`\`\`

*Link da Execução:*
${linkExec}

A execução deste fluxo foi interrompida ou apresentou inconsistências\\  
recomenda\\-se validação imediata do processo\\.`
};
